script:
$p = "$env:SystemRoot\System32\powercfg.exe"
$existing = (& $p /list) | Select-String 'Ultimate Performance'
if (-not $existing) { & $p /duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 | Out-Null; $existing = (& $p /list) | Select-String 'Ultimate Performance' }
$guid = ([regex]::Match(($existing | Select-Object -First 1).Line, '[0-9a-f\-]{36}')).Value
if ($guid) { & $p /setactive $guid; "Ultimate Performance active ($guid)" } else { 'This edition does not provide the Ultimate Performance plan.' }

$p = "$env:SystemRoot\System32\powercfg.exe"
$plans = [regex]::Matches(((& $p /list) -join "`n"), '[0-9a-f]{8}-[0-9a-f\-]{27}') | ForEach-Object { $_.Value } | Select-Object -Unique
foreach ($g in $plans) {
  foreach ($s in @(@('SUB_VIDEO','VIDEOIDLE'),@('SUB_VIDEO','VIDEOCONLOCK'),@('SUB_SLEEP','STANDBYIDLE'),@('SUB_SLEEP','HIBERNATEIDLE'),@('SUB_SLEEP','UNATTENDSLEEP'),@('SUB_DISK','DISKIDLE'))) {
    & $p /setacvalueindex $g $s[0] $s[1] 0 2>$null; & $p /setdcvalueindex $g $s[0] $s[1] 0 2>$null
  }
}
& $p /setactive SCHEME_CURRENT
"Updated $(@($plans).Count) power plan(s)."

undoScript:
$k = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
foreach ($n in 'TargetReleaseVersion','TargetReleaseVersionInfo','ProductVersion') { Remove-ItemProperty $k -Name $n -ErrorAction SilentlyContinue }
'Version pin removed'

script:
Get-Process OneDrive -ErrorAction SilentlyContinue | Stop-Process -Force
$wg = Get-RwWinget
if ($wg) { Invoke-RwNative $wg 'uninstall --id Microsoft.OneDrive --exact --silent --accept-source-agreements --disable-interactivity' | Out-Null }
$setup = "$env:SystemRoot\System32\OneDriveSetup.exe"; if (-not (Test-Path $setup)) { $setup = "$env:SystemRoot\SysWOW64\OneDriveSetup.exe" }
if (Test-Path $setup) { Start-Process $setup '/uninstall' -Wait }
'OneDrive uninstalled'

undoScript:
$wg = Get-RwWinget
if ($wg) { Invoke-RwNative $wg 'install --id Microsoft.OneDrive --exact --silent --accept-package-agreements --accept-source-agreements --disable-interactivity' | Out-Null }
'OneDrive reinstalled'
